import Fastify from 'fastify';
import fastifyStatic from '@fastify/static';
import { existsSync } from 'node:fs';
import { resolve } from 'node:path';
import { z } from 'zod';
import { ENGINE_VERSION,evaluate,demoInstance,defaultStrategy,presets,validateStrategy } from '../src/engine/index.ts';
import { Store } from './store.ts';
import { Jobs,JobError } from './jobs.ts';
import { AiClient,AiError } from './ai.ts';
import { aiProposeSchema,evaluateSchema,checkPair,evaluationSchema,regressionSchema,searchOptionsSchema,trustedEvaluation } from './validation.ts';
import { report } from './report.ts';
import type { Domain } from '../src/shared/types.ts';

class HttpError extends Error{constructor(message:string,public statusCode:number){super(message)}}
export interface AppOptions {dataDir?:string;staticDir?:string|false;env?:NodeJS.ProcessEnv;fetcher?:typeof fetch;jobTimeoutMs?:number}
export async function buildApp(options:AppOptions={}){
  const app=Fastify({logger:false,bodyLimit:4*1024*1024,requestTimeout:35000});
  const store=new Store(resolve(options.dataDir??resolve(process.cwd(),'.runtime'),'counterlab.sqlite'));
  const jobs=new Jobs(store,options.jobTimeoutMs);const ai=new AiClient(options.env,options.fetcher);
  app.addHook('onRequest',async(request,reply)=>{
    reply.header('X-Content-Type-Options','nosniff').header('Referrer-Policy','no-referrer');
    if(request.url.startsWith('/api/'))reply.header('Cache-Control','no-store');
    // Loopback binding alone does not protect against hostile DNS names resolving to it.
    try{const host=new URL(`http://${request.headers.host??''}`);if(!['localhost','127.0.0.1','[::1]'].includes(host.hostname)||host.username||host.password||host.pathname!=='/')throw new Error();}catch{throw new HttpError('只允许通过本机地址访问实验服务',403);}
    const origin=request.headers.origin;
    if(origin){try{const url=new URL(origin);if(!['localhost','127.0.0.1','[::1]'].includes(url.hostname)||!['http:','https:'].includes(url.protocol)||url.origin!==origin)throw new Error();}catch{throw new HttpError('不允许跨站请求本地实验服务',403);}}
  });
  app.setErrorHandler((error,request,reply)=>{
    if(error instanceof z.ZodError)return reply.code(400).send({error:error.issues.slice(0,5).map(issue=>`${issue.path.join('.')||'请求'}: ${issue.message}`).join('；')});
    if(error instanceof AiError||error instanceof HttpError||error instanceof JobError)return reply.code(error.statusCode).send({error:error.message});
    const status=(error as {statusCode?:number}).statusCode;
    if(status&&status>=400&&status<500)return reply.code(status).send({error:status===413?'请求内容过大':'请求格式或内容类型无效'});
    return reply.code(500).send({error:'服务处理失败，已有实验数据未改变。'});
  });
  const validated=<T>(fn:()=>T):T=>{try{return fn()}catch(error){if(error instanceof z.ZodError||error instanceof HttpError||error instanceof JobError)throw error;throw new HttpError(error instanceof Error?error.message:'输入无效',400)}};
  const getExperiment=(id:string)=>{const experiment=store.get(id);if(!experiment)throw new HttpError('实验不存在',404);return experiment};
  app.get('/api/health',async()=>({ok:true,engineVersion:ENGINE_VERSION}));
  app.get('/api/catalog',async()=>({engineVersion:ENGINE_VERSION,domains:([
    ['interval','区间调度','半开区间、明确目标：检查局部选择是否遗漏更好的兼容组合。'],
    ['knapsack','0-1资源分配','每件物品只能选择一次：比较收益、重量和密度策略。'],
    ['graph','非负权图路由','区分局部选择与全局距离，明确可达性和路径成本。']
  ] as [Domain,string,string][]).map(([domain,title,description])=>({domain,title,description,instance:demoInstance(domain),strategy:defaultStrategy(domain),presets:presets(domain)}))}));
  app.post('/api/evaluate',async request=>validated(()=>{const data=evaluateSchema.parse(request.body);checkPair(data.instance,data.strategy);return evaluate(data.instance,data.strategy)}));
  app.get('/api/experiments',async()=>store.list());
  app.post('/api/experiments',async request=>validated(()=>store.save(request.body)));
  app.get<{Params:{id:string}}>('/api/experiments/:id',async request=>getExperiment(request.params.id));
  app.put<{Params:{id:string}}>('/api/experiments/:id',async request=>{getExperiment(request.params.id);return validated(()=>store.save(request.body,request.params.id))});
  app.delete<{Params:{id:string}}>('/api/experiments/:id',async request=>{getExperiment(request.params.id);store.delete(request.params.id);return {ok:true}});
  app.get<{Params:{id:string}}>('/api/experiments/:id/export',async(request,reply)=>{getExperiment(request.params.id);reply.header('Content-Disposition',`attachment; filename="counterlab-${request.params.id}.json"`);return store.export(request.params.id)});
  app.post('/api/import',async request=>validated(()=>store.import(request.body)));
  app.get<{Params:{id:string}}>('/api/experiments/:id/report',async(request,reply)=>{const experiment=getExperiment(request.params.id);reply.type('text/html; charset=utf-8').header('Content-Security-Policy',"default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'").header('Content-Disposition',`attachment; filename="counterlab-${experiment.id}.html"`);return report(experiment,ENGINE_VERSION)});
  app.post('/api/jobs/search',async request=>validated(()=>{const data=searchOptionsSchema.parse(request.body);validateStrategy(data.strategy);if(data.domain!==data.strategy.domain)throw new Error('搜索领域与策略不一致');const max={interval:16,knapsack:18,graph:12}[data.domain];if(data.size>max)throw new Error('搜索实例规模超出领域上限');return jobs.create('search',data)}));
  app.post('/api/jobs/shrink',async request=>validated(()=>{const data=z.object({evaluation:evaluationSchema}).strict().parse(request.body);const evaluation=trustedEvaluation(data.evaluation);if(evaluation.verdict!=='counterexample')throw new Error('只有经过验证的反例才能缩减');return jobs.create('shrink',{evaluation})}));
  app.post('/api/jobs/regression',async request=>validated(()=>{const data=regressionSchema.parse(request.body);checkPair(data.instance,data.before);checkPair(data.instance,data.after);return jobs.create('regression',data)}));
  app.get<{Params:{id:string}}>('/api/jobs/:id',async request=>{const job=jobs.get(request.params.id);if(!job)throw new HttpError('任务不存在',404);return job});
  app.post<{Params:{id:string}}>('/api/jobs/:id/cancel',async request=>{const job=jobs.cancel(request.params.id);if(!job)throw new HttpError('任务不存在',404);return job});
  app.get('/api/ai/status',async()=>ai.status());
  app.post('/api/ai/propose',async request=>{const data=validated(()=>{const parsed=aiProposeSchema.parse(request.body);validateStrategy(parsed.currentStrategy);if(parsed.domain!==parsed.currentStrategy.domain)throw new Error('当前策略领域不一致');return parsed});return ai.propose(data)});
  app.post('/api/ai/explain',async request=>{const data=validated(()=>z.object({evaluation:evaluationSchema}).strict().parse(request.body));const evaluation=validated(()=>trustedEvaluation(data.evaluation));return ai.explain(evaluation)});
  const staticDir=options.staticDir===false?undefined:resolve(options.staticDir??resolve(process.cwd(),'dist'));
  if(staticDir&&existsSync(staticDir)){
    await app.register(fastifyStatic,{root:staticDir,index:'index.html'});
    app.setNotFoundHandler((request,reply)=>request.url.startsWith('/api/')?reply.code(404).send({error:'接口不存在'}):reply.sendFile('index.html'));
  }else app.setNotFoundHandler((_request,reply)=>reply.code(404).send({error:'接口不存在；开发界面请使用Vite，发行界面请先执行构建。'}));
  app.addHook('onClose',async()=>{await jobs.close();store.close()});
  return app;
}

# CounterLab development contract

## Filesystem and credentials
- Do not delete or modify any file on C:. All project files, dependency caches, temporary files, test profiles and runtimes must be written to D:.
- The user explicitly authorized ONLY newly generated image files under `C:/Users/MECHREVO/.codex/generated_images/` for the built-in image generator, followed by copying selected assets to this D: project. Do not delete or modify existing C: files. No other C: exception exists.
- Never commit API keys, SSH private keys, cookies, personal data or unredacted conversations. SSH configuration is outside this repository on D:.
- Install dependencies locally; do not modify global settings or system installations.

## Product and implementation
- Follow docs/DEVELOPMENT_PLAN.md. Build an original, local-first counterexample laboratory, not a fork or reskin of an existing application.
- Three domains: weighted/unweighted interval scheduling, 0-1 knapsack, nonnegative weighted graph routing.
- AI may propose typed contracts and explanations. Only deterministic execution and independently checked witnesses establish results.
- Never execute AI/user-generated JS, Python, shell or SQL. Interpret a bounded, validated strategy representation.
- Distinguish verified counterexample, finite exhaustive coverage, sampled-no-counterexample and incomplete search. Never claim a sampled result proves universal correctness.
- Every animation derives from real execution events. Shrinking must preserve validity and the original failure predicate.
- Preserve experiment versions, inputs, semantics, seeds, engine version and actual outputs for replay.

## Quality and history
- Keep changes modular and make truthful, incremental commits. Root agent owns git commits/pushes and shared package configuration.
- Record real development decisions and validation in evidence/; do not fabricate user conversations, bugs, reviews or test outcomes.
- Add meaningful tests for numerical semantics, reference agreement, shrinking, replay, API boundaries and end-to-end workflows.
- A worker is for responsiveness/resource management, not a security sandbox for arbitrary code.
- Use the user's requested image generation for high-quality original design reference and assets. Rebuild interactive parts as functional accessible components.
- Do not mark unimplemented or untested behavior complete. Report exact limits and evidence.

export type Domain = 'interval' | 'knapsack' | 'graph';
export type Objective = 'value' | 'count';
export interface IntervalItem { id: string; label: string; start: number; end: number; value: number }
export interface KnapsackItem { id: string; label: string; weight: number; value: number }
export interface GraphNode { id: string; label: string; x: number; y: number }
export interface GraphEdge { id: string; from: string; to: string; weight: number }
export interface IntervalInstance { domain: 'interval'; items: IntervalItem[]; objective: Objective }
export interface KnapsackInstance { domain: 'knapsack'; items: KnapsackItem[]; capacity: number }
export interface GraphInstance { domain: 'graph'; nodes: GraphNode[]; edges: GraphEdge[]; source: string; target: string; directed: boolean }
export type Instance = IntervalInstance | KnapsackInstance | GraphInstance;
export interface Strategy { id: string; name: string; domain: Domain; algorithm: 'greedy' | 'optimal' | 'dijkstra' | 'local'; score: string; direction: 'asc' | 'desc'; tieBreak: 'id' | 'value' | 'weight' | 'start' | 'end' }
export interface TraceStep { index: number; kind: 'consider' | 'select' | 'reject' | 'visit' | 'relax' | 'finish'; message: string; activeIds: string[]; selectedIds: string[]; currentValue: number; rejectedIds?: string[]; frontier?: {id:string;distance:number}[]; data?: Record<string,unknown> }
export interface Execution { solutionIds: string[]; value: number; feasible: boolean; complete: boolean; reason?: string; steps: TraceStep[]; pathNodeIds?: string[] }
export interface Evaluation { instance: Instance; strategy: Strategy; candidate: Execution; reference: Execution; verdict: 'counterexample' | 'pass' | 'invalid' | 'incomplete'; difference: number; witnessVerified: boolean; details: string[] }
export interface SearchOptions { domain: Domain; strategy: Strategy; seed: number; attempts: number; size: number; maxValue?: number; objective?: Objective }
export interface SearchProgress { checked: number; total: number; found: number }
export interface SearchResult { status: 'counterexample' | 'not_found' | 'incomplete'; checked: number; total: number; seed: number; elapsedMs: number; evaluation?: Evaluation; reason?: string; samples?: {index:number;gap:number}[] }
export interface ShrinkStep { description: string; beforeSize: number; afterSize: number; instance: Instance; evaluation: Evaluation }
export interface ShrinkResult { original: Evaluation; final: Evaluation; steps: ShrinkStep[]; checks: number; minimality: 'reduced' | 'local'; elapsedMs: number }
export interface RegressionRow { label: string; instance: Instance; before: Evaluation; after: Evaluation; change: 'improved' | 'regressed' | 'unchanged' }
export interface RegressionResult { rows: RegressionRow[]; improved: number; regressed: number; unchanged: number; seed: number }
export interface Experiment { id: string; title: string; domain: Domain; createdAt: string; updatedAt: string; instance: Instance; strategy: Strategy; versions: {id:string;at:string;strategy:Strategy;note:string}[]; evaluation?: Evaluation; search?: SearchResult; shrink?: ShrinkResult; regression?: RegressionResult }
export interface ExperimentPackage { format: 'counterlab-experiment'; version: 1; engineVersion: string; exportedAt: string; experiment: Experiment; checksum: string }
export interface JobStatus { id: string; kind: 'search' | 'shrink' | 'regression'; state: 'queued' | 'running' | 'completed' | 'cancelled' | 'failed'; progress: SearchProgress; result?: SearchResult | ShrinkResult | RegressionResult; error?: string }
export interface AiStatus { configured: boolean; provider: string; model: string; baseUrl: string; calls: number; inputTokens: number; outputTokens: number }
export interface AiProposal { strategy: Strategy; explanation: string; assumptions: string[]; source: 'live-model' }

import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { randomUUID,createHash,timingSafeEqual } from 'node:crypto';
import { ENGINE_VERSION } from '../src/engine/index.ts';
import type { Experiment,ExperimentPackage,JobStatus } from '../src/shared/types.ts';
import { packageSchema,trustedSave,validateExperimentVersions } from './validation.ts';

export function canonical(value:unknown):string {
  if(value===null||typeof value!=='object')return JSON.stringify(value);
  if(Array.isArray(value))return '['+value.map(canonical).join(',')+']';
  return '{'+Object.entries(value).filter(([,v])=>v!==undefined).sort(([a],[b])=>a<b?-1:a>b?1:0).map(([k,v])=>JSON.stringify(k)+':'+canonical(v)).join(',')+'}';
}
export function checksum(value:unknown){return createHash('sha256').update(canonical(value)).digest('hex')}
export class Store {
  private db:DatabaseSync;
  constructor(filename:string){
    const path=resolve(filename);if(process.platform==='win32' && !/^D:\\/i.test(path))throw new Error('数据库必须位于 D 盘');
    mkdirSync(dirname(path),{recursive:true});this.db=new DatabaseSync(path);
    this.db.exec('PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON; CREATE TABLE IF NOT EXISTS experiments(id TEXT PRIMARY KEY, updated_at TEXT NOT NULL, data TEXT NOT NULL); CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY, data TEXT NOT NULL)');
    for(const row of this.db.prepare('SELECT id,data FROM jobs').all()){
      const job=JSON.parse(String(row.data)) as JobStatus;
      if(job.state==='running'||job.state==='queued'){job.state='failed';job.error='服务已重启，本次任务中断。已保存的实验未受影响，请重新运行。';this.saveJob(job);}
    }
  }
  list():Experiment[]{return this.db.prepare('SELECT data FROM experiments ORDER BY updated_at DESC').all().map(row=>JSON.parse(String(row.data)))}
  get(id:string):Experiment|undefined {const row=this.db.prepare('SELECT data FROM experiments WHERE id=?').get(id);return row?JSON.parse(String(row.data)):undefined}
  save(input:unknown,id?:string):Experiment {
    const values=trustedSave(input);const previous=id?this.get(id):undefined;
    if(id&&!previous)throw new Error('实验不存在');
    if(previous && previous.domain!==values.instance.domain)throw new Error('已有实验不能切换领域，请另存新实验');
    const at=new Date().toISOString();const changed=!previous||canonical(previous.strategy)!==canonical(values.strategy);
    const versions=previous?[...previous.versions]:[];
    if(changed){if(versions.length>=200)throw new Error('策略版本已达到200个，请导出并创建新实验');versions.push({id:randomUUID(),at,strategy:values.strategy,note:previous?'策略修改':'初始策略'});}
    const experiment:Experiment={...values,id:previous?.id??randomUUID(),domain:values.instance.domain,createdAt:previous?.createdAt??at,updatedAt:at,versions} as Experiment;
    this.write(experiment);return experiment;
  }
  private write(experiment:Experiment){this.db.prepare('INSERT INTO experiments(id,updated_at,data) VALUES(?,?,?) ON CONFLICT(id) DO UPDATE SET updated_at=excluded.updated_at,data=excluded.data').run(experiment.id,experiment.updatedAt,JSON.stringify(experiment))}
  delete(id:string){return this.db.prepare('DELETE FROM experiments WHERE id=?').run(id).changes>0}
  export(id:string):ExperimentPackage|undefined {
    const experiment=this.get(id);if(!experiment)return undefined;
    const payload={format:'counterlab-experiment' as const,version:1 as const,engineVersion:ENGINE_VERSION,exportedAt:new Date().toISOString(),experiment};return {...payload,checksum:checksum(payload)};
  }
  import(input:unknown):Experiment {
    const pkg=packageSchema.parse(input);const {checksum:expected,...payload}=pkg;
    if(!timingSafeEqual(Buffer.from(expected,'hex'),Buffer.from(checksum(payload),'hex')))throw new Error('实验包校验和不匹配，文件可能已改变');
    if(pkg.engineVersion!==ENGINE_VERSION)throw new Error('执行器版本不兼容，不能静默迁移实验');
    validateExperimentVersions(pkg.experiment as Experiment);
