      <text className="object-axis" x={25} y={y + 17}>{item.id}</text><rect x={x(item.start)} y={y} width={Math.max(4, x(item.end) - x(item.start))} height={25} rx={4} />
      <text className="bar-text" x={x(item.start) + 10} y={y + 17}>{x(item.end) - x(item.start) > 72 ? `${item.id} · ${item.value}` : item.id}</text>
      {isSelected && x(item.end) - x(item.start) > 45 && <text className="bar-check" x={x(item.end) - 12} y={y + 17} textAnchor="middle">✓</text>}
    </g>; })}
  </svg>;
}

function KnapsackTrack({ instance, execution, step, tone, hovered, setHovered }: { instance: Extract<Instance,{domain:'knapsack'}>; execution?: Execution; step: number; tone: string; hovered: string | null; setHovered: (id:string|null) => void }) {
  const selected = selectedAt(execution, step); const active = stage(execution, step)?.activeIds ?? [];
  const weight = instance.items.filter(i => selected.includes(i.id)).reduce((total, item) => total + item.weight, 0);
  return <div className={`knapsack-plot ${tone}`}><div className="capacity-label"><span>已用容量 <b>{weight}</b> / {instance.capacity}</span><span>{Math.round(weight / Math.max(1, instance.capacity) * 100)}%</span></div><div className="capacity-track">{instance.items.filter(i => selected.includes(i.id)).map(item => <span key={item.id} style={{ width: `${item.weight / Math.max(1, instance.capacity) * 100}%` }} title={`${item.id}：重量 ${item.weight}`}>{item.id}</span>)}</div><div className="item-grid">{instance.items.map(item => <button key={item.id} className={`knapsack-item ${selected.includes(item.id) ? 'selected' : ''} ${active.includes(item.id) ? 'active' : ''} ${hovered === item.id ? 'hovered' : ''}`} onMouseEnter={() => setHovered(item.id)} onMouseLeave={() => setHovered(null)} onFocus={() => setHovered(item.id)} onBlur={() => setHovered(null)}><span className="item-corner">{item.id}</span><strong>{item.value}<small>收益</small></strong><span className="item-weight">重量 {item.weight}</span>{selected.includes(item.id) && <span className="item-selected">✓</span>}</button>)}</div></div>;
}

export function GraphPlot({ instance, execution, step = 0, tone = 'candidate', onChange }: { instance: GraphInstance; execution?: Execution; step?: number; tone?: string; onChange?: (instance: GraphInstance) => void }) {
  const svg = useRef<SVGSVGElement>(null);
  const drag = useRef<string | null>(null);
  const maxX = Math.max(1, ...instance.nodes.map(n => n.x)); const maxY = Math.max(1, ...instance.nodes.map(n => n.y));
  const positions = Object.fromEntries(instance.nodes.map((node, i) => [node.id, { x: 60 + (Number.isFinite(node.x) ? node.x / maxX : i / Math.max(1, instance.nodes.length - 1)) * 520, y: 35 + (Number.isFinite(node.y) ? node.y / maxY : 0.5) * 110 }]));
  const current = stage(execution, step); const selected = current?.selectedIds ?? []; const active = current?.activeIds ?? [];
  return <svg ref={svg} className={`graph-svg ${tone}`} viewBox="0 0 650 195" role="img" aria-label="路由网络与当前执行状态" onPointerMove={e => { if (!drag.current || !onChange || !svg.current) return; const rect = svg.current.getBoundingClientRect(); const rawX = (e.clientX - rect.left) / rect.width * 650; const rawY = (e.clientY - rect.top) / rect.height * 195; onChange({ ...instance, nodes: instance.nodes.map(n => n.id === drag.current ? { ...n, x: Math.max(0, Math.min(maxX, (rawX - 60) / 520 * maxX)), y: Math.max(0, Math.min(maxY, (rawY - 35) / 110 * maxY)) } : n) }); }} onPointerUp={() => { drag.current = null; }} onPointerCancel={() => { drag.current = null; }}>
    <defs><marker id={`arrow-${tone}`} viewBox="0 0 10 10" refX="25" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M 0 0 L 10 5 L 0 10 z" fill="currentColor" /></marker></defs>
    {instance.edges.map(edge => { const from = positions[edge.from]; const to = positions[edge.to]; if (!from || !to) return null; const picked = selected.includes(edge.id); return <g key={edge.id} className={`graph-edge ${picked ? 'selected' : ''} ${active.includes(edge.id) ? 'active' : ''}`}><line x1={from.x} y1={from.y} x2={to.x} y2={to.y} markerEnd={instance.directed ? `url(#arrow-${tone})` : undefined} /><rect x={(from.x + to.x) / 2 - 11} y={(from.y + to.y) / 2 - 10} width="22" height="20" rx="6" /><text x={(from.x + to.x) / 2} y={(from.y + to.y) / 2 + 4} textAnchor="middle">{edge.weight}</text></g>; })}
    {instance.nodes.map(node => { const position = positions[node.id]; const visited = selected.includes(node.id) || current?.data?.node === node.id || (execution?.pathNodeIds?.includes(node.id) && current?.kind === 'finish'); return <g key={node.id} className={`graph-node ${visited ? 'selected' : ''} ${active.includes(node.id) ? 'active' : ''}`} tabIndex={0} role="button" aria-label={`节点 ${node.id}${node.id === instance.source ? '，起点' : node.id === instance.target ? '，终点' : ''}`} onPointerDown={e => { if (onChange) { drag.current = node.id; e.currentTarget.setPointerCapture(e.pointerId); } }}><circle cx={position.x} cy={position.y} r="20" /><text x={position.x} y={position.y + 5} textAnchor="middle">{node.id}</text><text className="node-label" x={position.x} y={position.y + 37} textAnchor="middle">{node.id === instance.source ? '起点' : node.id === instance.target ? '终点' : node.label !== node.id ? node.label : ''}</text></g>; })}
  </svg>;
}

export function TraceCanvas({ instance, evaluation, step, hovered, setHovered }: { instance: Instance; evaluation: Evaluation | null; step: number; hovered: string | null; setHovered: (id:string|null) => void }) {
  const tracks = [{ key: 'candidate', label: '候选策略', caption: evaluation?.strategy.name || '等待执行', execution: evaluation?.candidate }, { key: 'reference', label: '精确参照', caption: '独立核验的最优结果', execution: evaluation?.reference }];
