    <button className="add-row" onClick={() => update(i => { if (i.domain === 'graph') i.edges.push({ id: nextId(i.edges.map(e => e.id), 'e'), from: i.nodes[0].id, to: i.nodes.at(-1)!.id, weight: 1 }); })}><Plus size={14} />添加一条边</button>
